import pandas as pd

def fx_rate(date: str) -> float:
    df = pd.read_csv('data/ecb_rates_2019.csv', parse_dates=['Date'])
    df['Date'] = pd.to_datetime(df['Date']).dt.strftime('%Y-%m-%d')
    row = df[df['Date'] == date]
    return float(row['Rate'].iloc[0])

def parse_price(s: str) -> float:
    s = s.replace('$', '').replace(',', '')
    return float(s)

def flatten(xs: list) -> list:
    result = []
    for item in xs:
        if isinstance(item, list):
            result.extend(flatten(item))
        else:
            result.append(item)
    return result

import json

def state_tax(state: str, amount: float) -> float:
    with open('scorer_cache/expected_state_tax.json') as f:
        tax_rates = json.load(f)
    rate = tax_rates.get(state.upper(), 0.0)
    return round(amount * rate, 2)

def second_largest(nums: list) -> int:
    unique_nums = list(set(nums))
    if len(unique_nums) < 2:
        raise ValueError('Not enough distinct elements')
    unique_nums.sort()
    return unique_nums[-2]
